        val entity = profile.toEntity(isActive = false)
        dao.upsert(entity)
        if (setActive) dao.setActive(profile.id)
    }

    suspend fun setActive(id: String) {
        dao.setActive(id)
    }

    suspend fun delete(id: String) {
        val active = dao.getActive()
        dao.deleteById(id)

        if (active?.id == id) {
